recipes.code:
{
  "inputs": [
    {
      "id": "crossdeck-secret-key",
      "type": "promptString",
      "description": "Your Crossdeck secret key (cd_sk_…) from the dashboard → API keys. Server-side only; never a publishable key.",
      "password": true
    }
  ],
  "servers": {
    "prism": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@cross-deck/ai@0.3.2"
      ],
      "env": {
        "CROSSDECK_SECRET_KEY": "${input:crossdeck-secret-key}",
        "CROSSDECK_API_BASE": "<crossdeck-api-base>"
      }
    }
  }
}
